You're trying to create a Rock-Paper-Scissors game in C++, but the code has several problems:

### Issues:
1. You declared a variable and a function with the same name `computer` — this is illegal.
2. You're calling `std:cout` instead of `std::cout`.
3. `score--` and `score+=0.5` are missing semicolons.
4. You're not calling the computer move function properly.
5. Conditionals like `if(computer == 0 && choice == 'S' || 's')` are logically wrong.
6. Repetitive if-statements with the same condition.
7. The switch block includes case 2, but `rand() % 2` only returns 0 or 1.

---

### ✅ Here is a corrected, complete version:

```cpp
#include <iostream>
#include <ctime>

int getComputerChoice() {
    srand(time(0));
    int q = rand() % 3; // 0 = Rock, 1 = Paper, 2 = Scissors
    return q;
}

std::string choiceToString(int choice) {
    switch (choice) {
        case 0: return "Rock";
        case 1: return "Paper";
        case 2: return "Scissors";
        default: return "";
    }
}

int main() {
    std::cout << "********** ROCK-PAPER-SCISSORS GAME **********\n";
    std::cout << "IF YOU WIN A GAME YOU GET +1, IF LOSE -1, TIE +0.5\n";
    std::cout << "CHOICES:\n";
    std::cout << "s for Scissors\n";
    std::cout << "r for Rock\n";
    std::cout << "p for Paper\n";

    char playerChoice;
    float score = 0;

    std::cout << "Enter your choice: ";
    std::cin >> playerChoice;

    int computerChoice = getComputerChoice();
    std::string computerMove = choiceToString(computerChoice);
    std::cout << "Computer chose: " << computerMove << "\n";

    // Normalize player choice to lowercase
    playerChoice = tolower(playerChoice);

    // Map: 0 = Rock, 1 = Paper, 2 = Scissors
    int player;
    if (playerChoice == 'r') player = 0;
    else if (playerChoice == 'p') player = 1;
    else if (playerChoice == 's') player = 2;
    else {
        std::cout << "Invalid input!\n";
        return 1;
    }

    if (player == computerChoice) {
        std::cout << "It's a tie!\n";
        score += 0.5;
    } else if ((player == 0 && computerChoice == 2) ||
               (player == 1 && computerChoice == 0) ||
               (player == 2 && computerChoice == 1)) {
        std::cout << "You win!\n";
        score += 1;
    } else {
        std::cout << "Computer wins!\n";
        score -= 1;
    }

    std::cout << "Your score: " << score << std::endl;

    return 0;
}
```

