### ✅ Final Version with `do-while`:

```cpp
#include <iostream>
#include <ctime>
#include <cstdlib>

int getComputerChoice() {
    return rand() % 3; // 0 = Rock, 1 = Paper, 2 = Scissors
}

std::string choiceToString(int choice) {
    switch (choice) {
        case 0: return "Rock";
        case 1: return "Paper";
        case 2: return "Scissors";
        default: return "";
    }
}

int main() {
    std::cout << "********** ROCK-PAPER-SCISSORS GAME **********\n";
    std::cout << "IF YOU WIN A GAME YOU GET +1, IF LOSE -1, TIE +0.5\n";
    std::cout << "CHOICES:\n";
    std::cout << "s for Scissors\n";
    std::cout << "r for Rock\n";
    std::cout << "p for Paper\n\n";

    char playerChoice, playAgain;
    float score = 0;

    srand(time(0)); // Initialize random seed only once

    do {
        std::cout << "Enter your choice (r/p/s): ";
        std::cin >> playerChoice;

        playerChoice = tolower(playerChoice);

        int player;
        if (playerChoice == 'r') player = 0;
        else if (playerChoice == 'p') player = 1;
        else if (playerChoice == 's') player = 2;
        else {
            std::cout << "Invalid input! Try again.\n";
            continue; // skip to next round
        }

        int computerChoice = getComputerChoice();
        std::string computerMove = choiceToString(computerChoice);
        std::cout << "Computer chose: " << computerMove << "\n";

        if (player == computerChoice) {
            std::cout << "It's a tie!\n";
            score += 0.5;
        } else if ((player == 0 && computerChoice == 2) ||
                   (player == 1 && computerChoice == 0) ||
                   (player == 2 && computerChoice == 1)) {
            std::cout << "You win!\n";
            score += 1;
        } else {
            std::cout << "Computer wins!\n";
            score -= 1;
        }

        std::cout << "Current score: " << score << "\n";
        std::cout << "Do you want to play again? (y/n): ";
        std::cin >> playAgain;
        playAgain = tolower(playAgain);
        std::cout << "--------------------------------------\n";

    } while (playAgain == 'y');

    std::cout << "Thanks for playing! Final score: " << score << std::endl;

    return 0;
}
```

